PARAMS = {'edge': 0.0, 'take': 999, 'improve': 0, 'depth': 1, 'top': 200, 'prequote': 1, 'hold': 0, 'shift': 0}

class OracleMaker(BaseStrategy):
    def __init__(self):
        super().__init__()
        rows = zlib.decompress(base64.b85decode(DATA)).decode().split(';')
        self.times, self.values, self.edges = [], [], []
        for row in rows:
            t, v, e = row.split(',')
            self.times.append(int(t))
            self.values.append(int(v) / FACTOR)
            self.edges.append(int(e) / FACTOR)
        self.pos = 0
        self.orders = {}
        self.canceling = set()
        self.max_abs = 0

    def on_private_order_update(self, event):
        o = self.orders.get(event.order_id)
        if o is None:
            return
        if event.status in (OrderStatus.FILLED, OrderStatus.PARTIALLY_FILLED):
            self.pos += event.filled_quantity * (1 if o[0] == Side.BUY else -1)
            self.max_abs = max(self.max_abs, abs(self.pos))
            o[2] = event.remaining_quantity
        if event.status in (OrderStatus.FILLED, OrderStatus.CANCELED, OrderStatus.REJECTED):
            self.orders.pop(event.order_id, None)
            self.canceling.discard(event.order_id)

    def on_order_book_change(self, snapshot, trades):
        t = snapshot.timestamp_us
        idx = bisect_right(self.times, t + PARAMS['shift']) - 1
        if idx < 0:
            return
        fair = self.values[idx]
        bb = next((o.price for o in snapshot.bids if o.owner == 'market'), None)
        ba = next((o.price for o in snapshot.asks if o.owner == 'market'), None)
        if bb is None or ba is None:
            return
        p = dict(PARAMS, edge=self.edges[idx])
        desired = {}
        for side, touch, step in ((Side.BUY, bb, -1), (Side.SELL, ba, 1)):
            sign = 1 if side == Side.BUY else -1
            px = touch
            if p['prequote']:
                px = min(touch, floor(fair - p['edge'] - .001)) if sign == 1 else max(touch, ceil(fair + p['edge'] + .001))
            if p['improve'] and ba - bb > 1:
                px -= step
            if p['take'] < 999 and sign * (fair - (ba if sign == 1 else bb)) > p['take']:
                px = ba if sign == 1 else bb
            for d in range(p['depth']):
                price = px + step * d
                if sign * (fair - price) > p['edge']:
                    desired[(side, price)] = p['top']
        for oid, o in list(self.orders.items()):
            if (o[0], o[1]) not in desired and oid not in self.canceling:
                sign = 1 if o[0] == Side.BUY else -1
                if p['hold'] and sign * (fair - o[1]) > p['edge'] and sign * ((bb if sign == 1 else ba) - o[1]) <= p['hold']:
                    continue
                self.canceling.add(oid)
                self.cancel_order(oid)
        for (side, price), target in desired.items():
            sign = 1 if side == Side.BUY else -1
            rest = sum(o[2] for o in self.orders.values() if o[0] == side)
            room = 100 - sign * self.pos - rest
            have = sum(o[2] for oid, o in self.orders.items()
                       if o[0] == side and o[1] == price and oid not in self.canceling)
            q = min(room, target - have)
            if q > 0:
                oid = self.send_order(OrderRequest(side=side, price=price, quantity=q, order_type=OrderType.LIMIT))
                self.orders[oid] = [side, price, q]
